import { useId } from "react"
import type * as React from "react"

import { cn } from "@/registry/mbank/lib/utils"
import { Card } from "@/registry/mbank/ui/card"

type TimelineProps = {
  title: string
  /** <TimelineItem /> elements, newest first. */
  children: React.ReactNode
  /** Shown instead of the list when there are no items. */
  empty?: React.ReactNode
  className?: string
}

/** Figma `History` card (История заявки): title 16 bold, items 12px apart. */
export function Timeline({ title, children, empty, className }: TimelineProps) {
  const titleId = useId()
  const hasItems = Array.isArray(children) ? children.length > 0 : Boolean(children)
  return (
    <Card
      role="region"
      aria-labelledby={titleId}
      data-slot="timeline"
      className={cn("gap-3 border-transparent p-5", className)}
    >
      <h2 id={titleId} className="text-base font-bold text-foreground">
        {title}
      </h2>
      {hasItems ? <ol className="flex flex-col gap-3">{children}</ol> : empty}
    </Card>
  )
}

import { StatusDot, type StatusDotTone } from "./StatusDot"

type TimelineItemProps = {
  title: string
  /** "12.10.2026, 10:02 · Система". */
  meta?: string
  tone?: StatusDotTone
  /** Machine-readable time for <time dateTime>. */
  dateTime?: string
}

/** Figma `CRM / Timeline item` (40px): 12px dot, title 14 medium, meta caption muted. */
export function TimelineItem({ title, meta, tone = "neutral", dateTime }: TimelineItemProps) {
  return (
    <li data-slot="timeline-item" className="flex gap-3">
      <StatusDot tone={tone} className="mt-1" />
      <div className="flex min-w-0 flex-col gap-1">
        <span className="text-sm font-medium text-foreground">{title}</span>
        {meta &&
          (dateTime ? (
            <time dateTime={dateTime} className="text-caption text-muted-foreground">
              {meta}
            </time>
          ) : (
            <span className="text-caption text-muted-foreground">{meta}</span>
          ))}
      </div>
    </li>
  )
}
